@@ -68,7 +68,7 @@ __device__ __forceinline__ void vec_neginf_fill(float* ptr, int n) {

 // -- main kernel -----------------------------------------------------------

-template <typename OutT>
+template <typename OutT, bool kUsePDL>
 __global__ void fixup_zero_kv_rows_kernel(
     OutT* __restrict__ out,
     float* __restrict__ lse,
@@ -88,14 +88,18 @@ __global__ void fixup_zero_kv_rows_kernel(
   const int tok = tok_start + blockIdx.x;
   if (tok >= tok_end) return;

+  device::PDLWaitPrimary<kUsePDL>();
+
   // Each block handles one token: zero out[tok] and set lse[tok] = -inf.
   vec_zero_fill(out + tok * out_stride, out_stride);
   vec_neginf_fill(lse + tok * lse_stride, lse_stride);
+
+  device::PDLTriggerSecondary<kUsePDL>();
 }

 // -- host launcher ---------------------------------------------------------

-template <typename OutT>
+template <typename OutT, bool kUsePDL>
 void fixup_zero_kv_rows(
     tvm::ffi::TensorView out,
     tvm::ffi::TensorView lse,
@@ -126,14 +130,15 @@ void fixup_zero_kv_rows(
   dim3 grid(blocks_x, bs);
   dim3 block(kFixupBlockSize);

-  LaunchKernel(grid, block, device.unwrap())(
-      fixup_zero_kv_rows_kernel<OutT>,
-      static_cast<OutT*>(out.data_ptr()),
-      static_cast<float*>(lse.data_ptr()),
-      static_cast<const int32_t*>(kv_lens.data_ptr()),
-      static_cast<const int32_t*>(cum_seq_lens.data_ptr()),
-      nh * vd,
-      nh);
+  LaunchKernel(grid, block, device.unwrap())
+      .enable_pdl(kUsePDL)(
+          fixup_zero_kv_rows_kernel<OutT, kUsePDL>,
+          static_cast<OutT*>(out.data_ptr()),
+          static_cast<float*>(lse.data_ptr()),
+          static_cast<const int32_t*>(kv_lens.data_ptr()),
+          static_cast<const int32_t*>(cum_seq_lens.data_ptr()),
+          nh * vd,
+          nh);
 }

 }  // namespace sglang

reviews.body:
@vincentzed @b8zhong I took a brief look at this PR. Good work! Implementation is quite clean so we can move forward but I recommend the followings

1. Break common changes into separate tiny PRs. I saw some changes about symm-mem (this part needs careful review), scheduler, small kernel changes, etc that are not specific to DCP x DSA

2. DCP x MTP - wait for https://github.com/sgl-project/sglang/pull/31785. Let's discuss further for GLM 5.2 MTP.
